package com.company.tpm.user; import com.company.tpm.authorization.Role; import com.company.tpm.common.BaseEntity; import com.company.tpm.employee.Employee; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="users") public class AppUser extends BaseEntity { @Column(nullable=false,unique=true) private String username; @Column(nullable=false) private String passwordHash; @Column(nullable=false) private boolean enabled=true; @Column(nullable=false) private boolean credentialsExpired=false; @OneToOne(fetch=FetchType.LAZY) private Employee employee; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="user_roles",joinColumns=@JoinColumn(name="user_id"),inverseJoinColumns=@JoinColumn(name="role_id")) private Set<Role> roles=new HashSet<>(); protected AppUser(){} public AppUser(String username,String passwordHash){this.username=username;this.passwordHash=passwordHash;} public void changePassword(String hash){this.passwordHash=hash;this.credentialsExpired=false;} public void addRole(Role role){roles.add(role);} public String getUsername(){return username;} public String getPasswordHash(){return passwordHash;} public boolean isEnabled(){return enabled;} public boolean isCredentialsExpired(){return credentialsExpired;} public Set<Role> getRoles(){return Set.copyOf(roles);} public Employee getEmployee(){return employee;} }
